/**
 * Golden vectors of the store2 format, committed as hex. Each hex string was
 * produced once by an oracle independent of the encoder (hand-sorted JSON text,
 * node:zlib CRC32, hand-written header bytes) and is never regenerated by the
 * code under test. `payload` is the JSON text inside the frame, kept for the
 * consistency check against the oracle in the test.
 */

import { crc32 } from 'node:zlib'

/**
 * Builds a frame byte by byte with `node:zlib`'s CRC32, independent of the
 * encoder under test, so an encoder bug cannot rewrite its own expectation.
 * `header` overrides single header bytes; the checksums still match them.
 */
export function oracleFrame(
    type: number,
    payloadText: string,
    header: { fmt?: number, codec?: number, reserved?: number } = {},
): Uint8Array {
    const payload = Buffer.from(payloadText, 'utf8')
    const head = Buffer.alloc(16)
    head.write('RSAL', 0, 'latin1')
    head[4] = header.fmt ?? 1
    head[5] = type
    head[6] = header.codec ?? 0
    head[7] = header.reserved ?? 0
    head.writeUInt32LE(payload.length, 8)
    head.writeUInt32LE(crc32(head.subarray(0, 12)), 12)
    const trailer = Buffer.alloc(4)
    trailer.writeUInt32LE(crc32(payload), 0)
    return new Uint8Array(Buffer.concat([head, payload, trailer]))
}

export function hexToBytes(hex: string): Uint8Array {
    return new Uint8Array(Buffer.from(hex, 'hex'))
}

export function bytesToHex(bytes: Uint8Array): string {
    return Buffer.from(bytes).toString('hex')
}

export interface GoldenVector {
    id: string
    /** The type byte in the frame (the id says which unit the body belongs to). */
    type: number
    fmt: number
    codec: number
    reserved: number
    payload: string
    hex: string
    /** The classification a reader must give: the frame result for header-level vectors, the parse result otherwise. */
    expect: 'ok' | 'damaged' | 'too-new' | 'unreadable'
    /** Whether the encoder can reproduce these bytes (a vector with a foreign header byte or a broken payload cannot be encoded). */
    encodable: boolean
}

